<template><section class="aw-records"><RouterLink :to="`/${slug}/clients`">← Clients</RouterLink><h1>{{ client?.full_name || client?.initials || 'Client chart' }}</h1><p v-if="error" role="alert">{{ error }}</p><p v-else-if="loading" role="status">Loading the practice chart…</p><template v-else><p class="aw-caption">{{ agency.name }} · Chart #{{ clientId }} · Existing care records</p><h2>Diagnoses</h2><ul v-if="chart.diagnoses?.length"><li v-for="d in chart.diagnoses" :key="d.id">{{ d.icd10_code }} {{ d.description }}</li></ul><p v-else>No diagnoses recorded.</p><h2>Treatment plan</h2><p>{{ chart.latestPlan?.title || 'No treatment plan recorded.' }} <span v-if="chart.latestPlan?.status">· {{ chart.latestPlan.status }}</span></p><h2>Clinical documentation</h2><div v-if="chart.notes?.length" class="aw-table"><table><thead><tr><th>Document</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="n in chart.notes" :key="n.id"><td>{{ n.title || `Note #${n.id}` }}</td><td>{{ n.note_type }}</td><td>{{ n.provider_signed_at ? 'Signed' : 'Draft' }}</td><td><RouterLink :to="{path:`/${slug}/documentation`,query:{clinicalNoteId:String(n.id),agencyId:String(agency.id)}}">Open in Documentation Hub →</RouterLink></td></tr></tbody></table></div><p v-else>No clinical notes recorded.</p></template></section></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';
import api from '../services/api';
const props=defineProps({clientId:String,agency:Object,slug:String});
const client=ref(null),chart=ref({}),loading=ref(true),error=ref('');let active=true;
onMounted(async()=>{try{const [c,r]=await Promise.all([api.get(`/clients/${props.clientId}`),api.get(`/medical-billing/clients/${props.clientId}/chart`,{params:{agencyId:props.agency.id}})]);if(active){client.value=c.data;chart.value=r.data;}}catch(e){if(active)error.value=e.response?.data?.error?.message||'Could not open this chart.';}finally{if(active)loading.value=false;}});onBeforeUnmount(()=>{active=false;});
</script>
